class PaymentProcessor(ABC):
    @abstractmethod
    def pay(self, order, security_code: str):
        pass

    def process_payment(self, order, verification_entity: str, entity_value: str):
        print(f"Processing payment using {verification_entity}")
        print(f"Verifying {verification_entity}: {entity_value}")
        order.status = "paid"

class CreditCardPaymentProcessor(PaymentProcessor):
    def pay(self, order, security_code: str):
        self.process_payment(order, 'credit card security code', security_code)

class DebitCardPaymentProcessor(PaymentProcessor):
    def pay(self, order, security_code: str):
        self.process_payment(order, 'debit card security code', security_code)

class PaypalPaymentProcessor(PaymentProcessor):
    def pay(self, order, email: str):
        self.process_payment(order, 'Paypal email', email)
